import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { Exercise, ExerciseSet, ExerciseMuscleInfo } from '../../types';
import { StarIcon, TrashIcon, ChevronDownIcon, ClockIcon, LinkIcon, SearchIcon, PlusIcon, FlameIcon, TrophyIcon } from '../icons';
import InlineSetTable from './InlineSetTable';
import FatigueIndicators from './FatigueIndicators';
import { SwipeDeleteHintModal } from './SwipeDeleteHintModal';
import { calculateHybrid1RM, suggestRestSeconds } from '../../utils/calculations';

interface ExerciseRowProps {
    exercise: Exercise;
    exerciseIndex: number;
    partIndex: number;
    exerciseList: ExerciseMuscleInfo[];
    isCulprit?: boolean;
    isExpertMode?: boolean;
    fatigue?: { msc: number; snc: number; spinal: number };
    augeSuggestion?: string | null;
    onUpdate: (partIndex: number, exerciseIndex: number, updater: (ex: Exercise) => void) => void;
    onRemove: (partIndex: number, exerciseIndex: number) => void;
    onReorder: (partIndex: number, exerciseIndex: number, direction: 'up' | 'down') => void;
    onLink: (partIndex: number, exerciseIndex: number) => void;
    onUnlink: (partIndex: number, exerciseIndex: number) => void;
    onAmrapToggle?: (partIndex: number, exerciseIndex: number, setIndex: number) => void;
    onOpenExerciseModal?: (partIndex: number, exerciseIndex: number) => void;
    scrollRef?: (el: HTMLDivElement | null) => void;
    dragHandleProps?: React.HTMLAttributes<HTMLDivElement>;
    weightUnit?: string;
}

const ExerciseRow: React.FC<ExerciseRowProps> = ({
    exercise, exerciseIndex, partIndex, exerciseList, isCulprit,
    isExpertMode, fatigue, augeSuggestion, onUpdate, onRemove, onReorder,
    onLink, onUnlink, onAmrapToggle, onOpenExerciseModal, scrollRef, dragHandleProps, weightUnit = 'kg',
}) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const [showSwipeHint, setShowSwipeHint] = useState(false);
    const wrapperRef = React.useRef<HTMLDivElement | null>(null);

    const setRef = useCallback((el: HTMLDivElement | null) => {
        wrapperRef.current = el;
        scrollRef?.(el);
    }, [scrollRef]);

    useEffect(() => {
        const el = wrapperRef.current;
        if (!el) return;
        const handler = () => {
            requestAnimationFrame(() => {
                el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
            });
        };
        el.addEventListener('focusin', handler);
        return () => el.removeEventListener('focusin', handler);
    }, [exercise.id]);
    const [isSearching, setIsSearching] = useState(!exercise.name);
    const [searchQuery, setSearchQuery] = useState('');

    const setsSummary = useMemo(() => {
        const sets = exercise.sets || [];
        if (sets.length === 0) return 'Sin series';
        const reps = sets.map(s => s.targetReps || 0);
        const allSame = reps.every(r => r === reps[0]);
        const intensityLabels: string[] = [];
        const hasRIR = sets.some(s => s.targetRIR !== undefined);
        const hasRPE = sets.some(s => s.targetRPE !== undefined);
        const hasFailure = sets.some(s => s.intensityMode === 'failure');
        const hasPercent = exercise.trainingMode === 'percent' && sets.some(s => (s as any).targetPercentageRM != null);
        if (hasFailure) intensityLabels.push('Fallo');
        else if (hasRIR) {
            const rirVals = sets.map(s => s.targetRIR).filter((r): r is number => r !== undefined);
            const avg = rirVals.length ? (rirVals.reduce((a, b) => a + b, 0) / rirVals.length).toFixed(1) : null;
            if (avg) intensityLabels.push(`RIR ${avg}`);
        } else if (hasRPE) {
            const rpeVals = sets.map(s => s.targetRPE).filter((r): r is number => r != null);
            const avg = rpeVals.length ? (rpeVals.reduce((a, b) => a + b, 0) / rpeVals.length).toFixed(1) : null;
            if (avg) intensityLabels.push(`@${avg}`);
        }
        if (hasPercent) {
            const pct = sets.map(s => (s as any).targetPercentageRM).filter(Boolean);
            if (pct.length) intensityLabels.push(`${Math.round((pct.reduce((a: number, b: number) => a + b, 0) as number) / pct.length)}%`);
        }
        const intStr = intensityLabels.length ? ` ${intensityLabels.join(' ')}` : '';
        if (allSame && reps[0]) return `${sets.length}x${reps[0]}${intStr}`;
        const minR = Math.min(...reps.filter(r => r > 0));
        const maxR = Math.max(...reps);
        return `${sets.length}x${minR}-${maxR}${intStr}`;
    }, [exercise.sets, exercise.trainingMode]);

    const filteredExercises = useMemo(() => {
        if (!searchQuery) return exerciseList.slice(0, 20);
        const normalizeText = (text: string) => text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        const searchTerms = normalizeText(searchQuery)
            .split(' ')
            .filter(t => t.length > 0 && !['de', 'con', 'en', 'el', 'la', 'los', 'las', 'y', 'a'].includes(t));

        return exerciseList.filter(e => {
            const searchTarget = normalizeText(
                `${e.name} ${e.equipment || ''} ${e.alias || ''} ${e.involvedMuscles?.map(m => m.muscle).join(' ') || ''}`
            );
            return searchTerms.every(term => searchTarget.includes(term));
        }).slice(0, 15);
    }, [searchQuery, exerciseList]);

    const handleSelectExercise = useCallback((ex: ExerciseMuscleInfo) => {
        onUpdate(partIndex, exerciseIndex, (draft) => {
            draft.name = ex.name;
            draft.exerciseDbId = ex.id;
        });
        setIsSearching(false);
        setSearchQuery('');
    }, [partIndex, exerciseIndex, onUpdate]);

    const handleSetChange = useCallback((setIndex: number, field: keyof ExerciseSet | Partial<ExerciseSet>, value?: any) => {
        onUpdate(partIndex, exerciseIndex, (draft) => {
            if (!draft.sets[setIndex]) return;
            if (typeof field === 'string') {
                (draft.sets[setIndex] as any)[field] = value;
            } else {
                Object.assign(draft.sets[setIndex], field);
            }
        });
    }, [partIndex, exerciseIndex, onUpdate]);

    const handleAddSet = useCallback(() => {
        onUpdate(partIndex, exerciseIndex, (draft) => {
            const last = draft.sets[draft.sets.length - 1];
            const defaultMode = draft.trainingMode === 'percent' ? 'solo_rm' : (last?.intensityMode || 'rpe');
            draft.sets.push({
                id: crypto.randomUUID(),
                targetReps: last?.targetReps || 10,
                targetRPE: last?.targetRPE || 8,
                intensityMode: last?.intensityMode || defaultMode,
            });
        });
    }, [partIndex, exerciseIndex, onUpdate]);

    const handleRemoveSet = useCallback((setIndex: number) => {
        onUpdate(partIndex, exerciseIndex, (draft) => {
            draft.sets.splice(setIndex, 1);
        });
    }, [partIndex, exerciseIndex, onUpdate]);

    // RM efectivo para cargas sugeridas: usa reference1RM o lo calcula de prFor1RM al vuelo
    const effectiveReference1RM = useMemo(() => {
        if (exercise.reference1RM && exercise.reference1RM > 0) return exercise.reference1RM;
        if (exercise.prFor1RM?.weight && exercise.prFor1RM?.reps)
            return calculateHybrid1RM(exercise.prFor1RM.weight, exercise.prFor1RM.reps);
        return undefined;
    }, [exercise.reference1RM, exercise.prFor1RM?.weight, exercise.prFor1RM?.reps]);

    // Persistir reference1RM desde PR cuando prFor1RM está definido (modo percent)
    useEffect(() => {
        if (exercise.trainingMode !== 'percent' || !exercise.prFor1RM?.weight || !exercise.prFor1RM?.reps) return;
        const e1rm = calculateHybrid1RM(exercise.prFor1RM.weight, exercise.prFor1RM.reps);
        if (e1rm > 0 && Math.abs((exercise.reference1RM || 0) - e1rm) > 0.1) {
            onUpdate(partIndex, exerciseIndex, (draft) => {
                draft.reference1RM = e1rm;
            });
        }
    }, [exercise.trainingMode, exercise.prFor1RM?.weight, exercise.prFor1RM?.reps, exercise.reference1RM, partIndex, exerciseIndex, onUpdate]);

    const formatRest = (seconds: number) => {
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}:${s.toString().padStart(2, '0')}`;
    };

    // Si hay modal disponible, abrir el modal con categorías y AUGE en lugar del dropdown inline
    useEffect(() => {
        if (isSearching && onOpenExerciseModal) {
            onOpenExerciseModal(partIndex, exerciseIndex);
            setIsSearching(false);
        }
    }, [isSearching, onOpenExerciseModal, partIndex, exerciseIndex]);

    if (isSearching && !onOpenExerciseModal) {
        // Fallback: dropdown inline solo cuando no hay modal (ej. ProgramEditor u otros contextos)
        return (
            <div ref={setRef} className="px-4 py-3 border-b border-[#E6E0E9] animate-fade-in scroll-mb-48">
                <div className="relative mb-2">
                    <SearchIcon size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#555]" />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        placeholder="Buscar ejercicio..."
                        autoFocus
                        className="w-full bg-[#0d0d0d] border-b border-[#E6E0E9] focus:border-[#00F0FF] pl-9 pr-3 py-2.5 text-sm text-white placeholder-[#555] outline-none transition-colors"
                    />
                </div>
                <div className="max-h-48 overflow-y-auto custom-scrollbar space-y-0.5">
                    {filteredExercises.map(ex => (
                        <button
                            key={ex.id || ex.name}
                            onClick={() => handleSelectExercise(ex)}
                            className="w-full text-left px-3 py-2 rounded-lg hover:bg-white/5 transition-colors"
                        >
                            <span className="text-sm font-medium text-white">{ex.name}</span>
                            <span className="text-[10px] text-[#555] ml-2">
                                {ex.involvedMuscles?.filter(m => m.role === 'primary').map(m => m.muscle).join(', ')}
                            </span>
                        </button>
                    ))}
                </div>
                {exercise.name && (
                    <button onClick={() => setIsSearching(false)} className="w-full mt-2 py-1.5 text-xs font-medium text-[#555] hover:text-white transition-colors">
                        Cancelar
                    </button>
                )}
            </div>
        );
    }

    return (
        <div
            ref={setRef}
            className={`border-b transition-colors scroll-mb-48 ${isCulprit ? 'border-red-500/20 bg-red-950/5' : 'border-[#E6E0E9]'}`}
        >
            {/* Collapsed row */}
            <button
                onClick={() => setIsExpanded(!isExpanded)}
                className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-white/[0.02] transition-colors"
            >
                {/* Grip handle (drag) */}
                <div {...(dragHandleProps || {})} className={`w-6 flex flex-col items-center justify-center gap-0.5 shrink-0 cursor-grab active:cursor-grabbing ${dragHandleProps ? 'opacity-60 hover:opacity-100' : 'opacity-30 hover:opacity-60'} transition-opacity touch-none`}>
                    <div className="w-3 h-0.5 bg-[#555] rounded-full" />
                    <div className="w-3 h-0.5 bg-[#555] rounded-full" />
                </div>

                {/* Exercise name */}
                <button
                    onClick={e => {
                        e.stopPropagation();
                        if (onOpenExerciseModal) onOpenExerciseModal(partIndex, exerciseIndex);
                        else setIsSearching(true);
                    }}
                    className="text-sm font-medium text-white truncate hover:text-[#00F0FF] transition-colors text-left min-w-0 flex-1"
                >
                    {exercise.name || 'Seleccionar ejercicio'}
                </button>

                {/* Sets summary */}
                <span className="text-xs font-mono text-[#999] shrink-0">{setsSummary}</span>

                {/* Fatigue indicators */}
                {fatigue && <FatigueIndicators msc={fatigue.msc} snc={fatigue.snc} spinal={fatigue.spinal} />}

                {/* Competition / Star */}
                {exercise.isCompetitionLift && <TrophyIcon size={12} className="text-orange-400 shrink-0" />}
                {exercise.isStarTarget && <StarIcon size={12} filled className="text-yellow-400 shrink-0" />}

                {/* Expand chevron */}
                <ChevronDownIcon
                    size={14}
                    className={`text-[#555] transition-transform shrink-0 ${isExpanded ? 'rotate-180' : ''}`}
                />
            </button>

            {/* Expanded content */}
            {isExpanded && (
                <div className="px-4 pb-4 space-y-3 animate-fade-in">
                    {/* AUGE suggestion */}
                    {augeSuggestion && (
                        <div className="flex items-start gap-2 px-3 py-2 rounded-lg bg-[#00F0FF]/5 border border-[#00F0FF]/10">
                            <span className="text-[10px] text-[#00F0FF] leading-relaxed">{augeSuggestion}</span>
                        </div>
                    )}

                    {/* Config row */}
                    <div className="flex items-center gap-3 flex-wrap">
                        <div className="flex items-center gap-1">
                            <ClockIcon size={12} className="text-[#555]" />
                            <div className="flex items-center gap-0.5">
                                <input
                                    type="number"
                                    inputMode="numeric"
                                    min={0}
                                    max={5}
                                    value={Math.floor((Math.min(300, exercise.restTime || 90)) / 60)}
                                    onChange={e => {
                                        const m = Math.min(5, Math.max(0, parseInt(e.target.value, 10) || 0));
                                        const sec = (exercise.restTime || 90) % 60;
                                        onUpdate(partIndex, exerciseIndex, d => { d.restTime = Math.min(300, m * 60 + sec); });
                                    }}
                                    className="w-8 bg-transparent border-b border-[#E6E0E9] focus:border-[#00F0FF] text-[10px] font-mono text-white text-center py-0.5 outline-none transition-colors"
                                    placeholder="0"
                                />
                                <span className="text-[#555] text-[10px]">:</span>
                                <input
                                    type="number"
                                    inputMode="numeric"
                                    min={0}
                                    max={59}
                                    value={(exercise.restTime || 90) % 60}
                                    onChange={e => {
                                        const sec = Math.min(59, Math.max(0, parseInt(e.target.value, 10) || 0));
                                        const m = Math.floor((Math.min(300, exercise.restTime || 90)) / 60);
                                        onUpdate(partIndex, exerciseIndex, d => { d.restTime = Math.min(300, m * 60 + sec); });
                                    }}
                                    className="w-8 bg-transparent border-b border-[#E6E0E9] focus:border-[#00F0FF] text-[10px] font-mono text-white text-center py-0.5 outline-none transition-colors"
                                    placeholder="00"
                                />
                            </div>
                            {exercise.sets?.length > 0 && (() => {
                                const avgRPE = exercise.sets.filter(s => (s.targetRPE ?? s.targetRIR) != null).reduce((a, s) => a + (s.targetRPE ?? (s.targetRIR != null ? 10 - s.targetRIR : 8)), 0) / Math.max(1, exercise.sets.filter(s => (s.targetRPE ?? s.targetRIR) != null).length) || 8;
                                const avgPercent1RM = exercise.trainingMode === 'percent' && exercise.sets?.length ? exercise.sets.reduce((a, s) => a + ((s as any).targetPercentageRM || 0), 0) / exercise.sets.length : undefined;
                                const suggested = suggestRestSeconds(exercise.sets.length, avgRPE, avgPercent1RM);
                                const current = exercise.restTime || 90;
                                if (Math.abs(suggested - current) > 15) {
                                    return <button type="button" onClick={() => onUpdate(partIndex, exerciseIndex, d => { d.restTime = suggested; })} className="text-[8px] font-bold text-cyber-cyan hover:text-cyber-cyan/80">Sug</button>;
                                }
                                return null;
                            })()}
                        </div>

                        <select
                            value={exercise.trainingMode || 'reps'}
                            onChange={e => onUpdate(partIndex, exerciseIndex, d => { d.trainingMode = e.target.value as any; })}
                            className="bg-transparent text-[10px] font-bold text-[#999] border-b border-[#E6E0E9] focus:border-[#00F0FF] py-0.5 px-1 outline-none cursor-pointer"
                        >
                            <option value="reps" className="bg-black">Reps</option>
                            <option value="percent" className="bg-black">% 1RM</option>
                            <option value="time" className="bg-black">Tiempo</option>
                            <option value="custom" className="bg-black">Libre</option>
                        </select>

                        {exercise.trainingMode === 'percent' && (
                            <div className="flex items-center gap-2 flex-wrap">
                                <div className="flex items-center gap-1">
                                    <span className="text-[10px] text-[#555]">1RM:</span>
                                    <input
                                        type="number"
                                        step="0.5"
                                        value={exercise.reference1RM ?? ''}
                                        onChange={e => onUpdate(partIndex, exerciseIndex, d => { const v = e.target.value; d.reference1RM = v === '' ? undefined : (parseFloat(v) ?? undefined); })}
                                        placeholder="kg"
                                        className="w-14 bg-white/[0.03] border-b border-cyber-cyan/20 focus:border-cyber-cyan/60 text-xs font-mono text-white text-center py-0.5 rounded outline-none"
                                    />
                                </div>
                                <div className="flex items-center gap-1">
                                    <span className="text-[10px] text-[#555]">o PR:</span>
                                    <input
                                        type="number"
                                        step="0.5"
                                        value={exercise.prFor1RM?.weight != null && exercise.prFor1RM.weight !== 0 ? exercise.prFor1RM.weight : ''}
                                        onChange={e => {
                                            const v = e.target.value;
                                            const w = v === '' ? undefined : (parseFloat(v) ?? undefined);
                                            onUpdate(partIndex, exerciseIndex, d => {
                                                d.prFor1RM = { weight: w ?? 0, reps: d.prFor1RM?.reps ?? 1 };
                                            });
                                        }}
                                        placeholder="kg"
                                        className="w-12 bg-white/[0.03] border-b border-cyber-cyan/20 focus:border-cyber-cyan/60 text-xs font-mono text-white text-center py-0.5 rounded outline-none"
                                    />
                                    <span className="text-[10px] text-[#555]">×</span>
                                    <input
                                        type="number"
                                        min={1}
                                        max={30}
                                        value={exercise.prFor1RM?.reps != null && exercise.prFor1RM.reps !== 0 ? exercise.prFor1RM.reps : ''}
                                        onChange={e => {
                                            const v = e.target.value;
                                            const r = v === '' ? undefined : Math.min(30, Math.max(1, parseInt(v, 10) || 1));
                                            onUpdate(partIndex, exerciseIndex, d => {
                                                d.prFor1RM = { weight: d.prFor1RM?.weight ?? 0, reps: r ?? 1 };
                                            });
                                        }}
                                        placeholder="r"
                                        className="w-10 bg-white/[0.03] border-b border-cyber-cyan/20 focus:border-cyber-cyan/60 text-xs font-mono text-white text-center py-0.5 rounded outline-none"
                                    />
                                </div>
                            </div>
                        )}

                        {exercise.trainingMode === 'reps' && (
                            <div className="flex items-center gap-1">
                                <span className="text-[10px] text-[#555]">Peso ref:</span>
                                <input
                                    type="number"
                                    step="0.5"
                                    value={exercise.consolidatedWeight?.weightKg != null && exercise.consolidatedWeight.weightKg !== 0 ? exercise.consolidatedWeight.weightKg : ''}
                                    onChange={e => {
                                        const v = e.target.value;
                                        const w = v === '' ? undefined : (parseFloat(v) ?? undefined);
                                        onUpdate(partIndex, exerciseIndex, d => {
                                            d.consolidatedWeight = { weightKg: w ?? 0, reps: d.consolidatedWeight?.reps ?? 10 };
                                        });
                                    }}
                                    placeholder="kg"
                                    className="w-12 bg-white/[0.03] border-b border-cyber-cyan/20 focus:border-cyber-cyan/60 text-xs font-mono text-white text-center py-0.5 rounded outline-none"
                                />
                                <span className="text-[10px] text-[#555]">×</span>
                                <input
                                    type="number"
                                    min={1}
                                    max={99}
                                    value={exercise.consolidatedWeight?.reps != null && exercise.consolidatedWeight.reps !== 0 ? exercise.consolidatedWeight.reps : ''}
                                    onChange={e => {
                                        const v = e.target.value;
                                        const r = v === '' ? undefined : Math.min(99, Math.max(1, parseInt(v, 10) || 10));
                                        onUpdate(partIndex, exerciseIndex, d => {
                                            d.consolidatedWeight = { weightKg: d.consolidatedWeight?.weightKg ?? 0, reps: r ?? 10 };
                                        });
                                    }}
                                    placeholder="r"
                                    className="w-10 bg-white/[0.03] border-b border-cyber-cyan/20 focus:border-cyber-cyan/60 text-xs font-mono text-white text-center py-0.5 rounded outline-none"
                                />
                            </div>
                        )}

                        <div className="flex-1" />

                        {/* Actions */}
                        <button onClick={() => onUpdate(partIndex, exerciseIndex, d => { d.isCompetitionLift = !d.isCompetitionLift; })} className={`p-1 ${exercise.isCompetitionLift ? 'text-orange-400' : 'text-[#555] hover:text-orange-400'} transition-colors`} title="Competition Lift">
                            <TrophyIcon size={12} />
                        </button>
                        <button onClick={() => onUpdate(partIndex, exerciseIndex, d => { d.isStarTarget = !d.isStarTarget; })} className={`p-1 ${exercise.isStarTarget ? 'text-yellow-400' : 'text-[#555] hover:text-yellow-400'} transition-colors`}>
                            <StarIcon size={12} filled={exercise.isStarTarget} />
                        </button>
                        <button onClick={() => onLink(partIndex, exerciseIndex)} className="p-1 text-[#555] hover:text-white transition-colors" title="Biserie">
                            <LinkIcon size={12} />
                        </button>
                        <button onClick={() => onRemove(partIndex, exerciseIndex)} className="p-1 text-[#555] hover:text-red-400 transition-colors">
                            <TrashIcon size={12} />
                        </button>
                    </div>

                    {/* Sets table */}
                    <InlineSetTable
                        sets={exercise.sets || []}
                        trainingMode={exercise.trainingMode}
                        onSetChange={handleSetChange}
                        onAddSet={handleAddSet}
                        onRemoveSet={handleRemoveSet}
                        onAmrapToggle={onAmrapToggle ? (setIdx) => onAmrapToggle(partIndex, exerciseIndex, setIdx) : undefined}
                        reference1RM={effectiveReference1RM}
                        onFirstAddSet={() => { try { if (!localStorage.getItem('kpkn_seen_swipe_delete_hint')) setShowSwipeHint(true); } catch (_) { } }}
                        weightUnit={weightUnit}
                    />
                    {showSwipeHint && <SwipeDeleteHintModal onClose={() => setShowSwipeHint(false)} />}
                </div>
            )}
        </div>
    );
};

export default ExerciseRow;
