import React, { useState, useEffect, useRef } from 'react';
import { Session, Exercise, ExerciseMuscleInfo, WarmupSetDefinition } from '../../types';
import { XIcon, SearchIcon, PlusIcon, TrashIcon, CheckIcon, LayersIcon } from '../icons';
import Button from '../ui/Button';

interface DrawerProps {
    isOpen: boolean;
    onClose: () => void;
    position?: 'right' | 'bottom';
    height?: string;
    title: string;
    children: React.ReactNode;
}

const Drawer: React.FC<DrawerProps> = ({ isOpen, onClose, position = 'right', height = '80%', title, children }) => {
    if (!isOpen) return null;

    const isBottom = position === 'bottom';
    const posClasses = isBottom
        ? `bottom-0 left-0 right-0 rounded-t-2xl`
        : `top-0 right-0 bottom-0 w-[340px] max-w-[90vw]`;
    const animClass = isBottom ? 'animate-slide-up' : 'animate-slide-left';

    return (
        <>
            <div className="fixed inset-0 z-[110] bg-black/40" onClick={onClose} />
            <div
                className={`fixed z-[111] bg-[#ECE6F0] border-white/[0.08] flex flex-col ${posClasses} ${animClass}`}
                style={isBottom ? { height, borderTop: '1px solid rgba(255,255,255,0.08)' } : { borderLeft: '1px solid rgba(255,255,255,0.08)' }}
            >
                <div className="flex items-center justify-between px-4 py-3 border-b border-white/[0.08] shrink-0">
                    <h3 className="text-sm font-semibold text-white">{title}</h3>
                    <button onClick={onClose} className="text-[#555] hover:text-white transition-colors">
                        <XIcon size={16} />
                    </button>
                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {children}
                </div>
            </div>
        </>
    );
};

/* ═══════════ Transfer Drawer ═══════════ */
interface TransferDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    weekSessions: Session[];
    activeSessionId: string;
    session: Session;
    onTransfer: (mode: 'export' | 'import', targetId: string) => void;
}

export const TransferDrawer: React.FC<TransferDrawerProps> = ({ isOpen, onClose, weekSessions, activeSessionId, session, onTransfer }) => {
    const [mode, setMode] = useState<'export' | 'import'>('export');
    const [targetId, setTargetId] = useState('');

    return (
        <Drawer isOpen={isOpen} onClose={onClose} title="Transferencia de Sesión" position="right">
            <div className="p-4 space-y-4">
                <div className="flex gap-1 bg-white/5 p-1 rounded-lg">
                    <button onClick={() => setMode('export')} className={`flex-1 py-2 text-[10px] font-bold rounded-md transition-all ${mode === 'export' ? 'bg-white text-black' : 'text-[#999]'}`}>Exportar</button>
                    <button onClick={() => setMode('import')} className={`flex-1 py-2 text-[10px] font-bold rounded-md transition-all ${mode === 'import' ? 'bg-white text-black' : 'text-[#999]'}`}>Importar</button>
                </div>
                <p className="text-xs text-[#999]">Selecciona la sesión de {mode === 'export' ? 'destino' : 'origen'}:</p>
                <div className="space-y-2">
                    {weekSessions.filter(s => s.id !== activeSessionId).map(s => (
                        <button key={s.id} onClick={() => setTargetId(s.id)} className={`w-full p-3 text-left rounded-lg border text-xs font-medium transition-all ${targetId === s.id ? 'bg-[#00F0FF]/10 border-[#00F0FF]/30 text-white' : 'bg-white/[0.02] border-white/[0.06] text-[#999] hover:border-[#E6E0E9]'}`}>
                            {s.name || `Sesión Día ${s.dayOfWeek}`}
                            <span className="block text-[10px] text-[#555] mt-0.5">
                            {(s.parts && s.parts.length > 0)
                                ? s.parts.reduce((acc, p) => acc + (p.exercises?.length || 0), 0)
                                : (s.exercises?.length || 0)
                            } Ejercicios</span>
                        </button>
                    ))}
                </div>
                {targetId && (
                    <button onClick={() => { onTransfer(mode, targetId); onClose(); }} className="w-full py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">
                        Confirmar Transferencia
                    </button>
                )}
            </div>
        </Drawer>
    );
};

/* ═══════════ Warmup Drawer ═══════════ */
interface WarmupDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    exerciseName: string;
    warmupSets: WarmupSetDefinition[];
    onSave: (sets: WarmupSetDefinition[]) => void;
}

export const WarmupDrawer: React.FC<WarmupDrawerProps> = ({ isOpen, onClose, exerciseName, warmupSets, onSave }) => {
    const [sets, setSets] = useState<WarmupSetDefinition[]>([]);

    useEffect(() => {
        if (isOpen) setSets(warmupSets.length > 0 ? [...warmupSets] : [{ id: crypto.randomUUID(), percentageOfWorkingWeight: 50, targetReps: 10 }]);
    }, [isOpen, warmupSets]);

    const addSet = () => {
        const last = sets[sets.length - 1];
        setSets([...sets, {
            id: crypto.randomUUID(),
            percentageOfWorkingWeight: last ? Math.min(90, last.percentageOfWorkingWeight + 10) : 50,
            targetReps: last ? Math.max(1, Math.floor(last.targetReps / 2)) : 10,
        }]);
    };

    return (
        <Drawer isOpen={isOpen} onClose={onClose} title={`Aproximación: ${exerciseName}`} position="bottom" height="50%">
            <div className="p-4 space-y-3">
                {sets.map((set, i) => (
                    <div key={set.id} className="flex items-center gap-2">
                        <span className="w-6 text-xs font-mono text-[#999] text-center">{i + 1}</span>
                        <div className="flex-1">
                            <span className="text-[10px] text-[#555] block">Carga %</span>
                            <input type="number" value={set.percentageOfWorkingWeight === 0 ? '' : set.percentageOfWorkingWeight} onChange={e => { const v = e.target.value; const u = [...sets]; u[i].percentageOfWorkingWeight = v === '' ? 0 : (parseFloat(v) || 0); setSets(u); }} className="w-full bg-transparent border-b border-[#E6E0E9] focus:border-[#00F0FF] text-sm font-mono text-white py-0.5 outline-none" />
                        </div>
                        <div className="w-16">
                            <span className="text-[10px] text-[#555] block">Reps</span>
                            <input type="number" value={set.targetReps === 0 ? '' : set.targetReps} onChange={e => { const v = e.target.value; const u = [...sets]; u[i].targetReps = v === '' ? 0 : (parseFloat(v) || 0); setSets(u); }} className="w-full bg-transparent border-b border-[#E6E0E9] focus:border-[#00F0FF] text-sm font-mono text-white py-0.5 text-center outline-none" />
                        </div>
                        <button onClick={() => setSets(sets.filter((_, idx) => idx !== i))} className="text-[#555] hover:text-red-400 transition-colors mt-3">
                            <XIcon size={12} />
                        </button>
                    </div>
                ))}
                <button onClick={addSet} className="flex items-center gap-1.5 text-[#555] hover:text-[#00F0FF] text-xs font-medium transition-colors">
                    <PlusIcon size={12} /> Agregar serie
                </button>
                <div className="flex gap-2 pt-3 border-t border-white/[0.08]">
                    <button onClick={onClose} className="flex-1 py-2.5 rounded-lg text-xs font-medium text-[#999] hover:bg-white/5 transition-all">Cancelar</button>
                    <button onClick={() => { onSave(sets); onClose(); }} className="flex-1 py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">Guardar</button>
                </div>
            </div>
        </Drawer>
    );
};

/* ═══════════ History Drawer ═══════════ */
interface HistoryDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    sessionHistory: Session[];
    onRestore: (session: Session) => void;
}

export const HistoryDrawer: React.FC<HistoryDrawerProps> = ({ isOpen, onClose, sessionHistory, onRestore }) => {
    return (
        <Drawer isOpen={isOpen} onClose={onClose} title="Historial de Cambios" position="right">
            <div className="p-4 space-y-2">
                {sessionHistory.length === 0 ? (
                    <p className="text-xs text-[#555] text-center py-8">No hay cambios recientes.</p>
                ) : [...sessionHistory].reverse().map((hist, idx) => (
                    <button
                        key={idx}
                        onClick={() => { onRestore(hist); onClose(); }}
                        className="w-full text-left p-3 border border-white/[0.06] hover:border-[#E6E0E9] rounded-lg text-xs transition-all group"
                    >
                        <span className="text-white font-medium group-hover:text-[#00F0FF]">
                            Estado #{sessionHistory.length - idx}
                        </span>
                        <span className="text-[10px] text-[#555] ml-2">Restaurar</span>
                    </button>
                ))}
            </div>
        </Drawer>
    );
};

/* ═══════════ Rules Drawer (Ampliado) ═══════════ */
export type RulesScope = 'session' | 'section' | 'week' | 'block';

export interface RulesApplyPayload {
    action: 'defaults' | 'limits';
    sets?: number;
    reps?: number;
    rpe?: number;
    scope?: RulesScope;
    sectionIndex?: number;
    maxExercisesPerMuscle?: number;
    maxRPE?: number;
}

interface RulesDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    onApply: (payload: RulesApplyPayload) => void;
    sectionNames?: string[];
    initialLimits?: { maxRPE?: number; maxExercisesPerMuscle?: number };
}

export const RulesDrawer: React.FC<RulesDrawerProps> = ({ isOpen, onClose, onApply, sectionNames = [], initialLimits }) => {
    const [sets, setSets] = useState<number | ''>(3);
    const [reps, setReps] = useState<number | ''>(10);
    const [rpe, setRpe] = useState<number | ''>(8);
    const [scope, setScope] = useState<RulesScope>('session');
    const [sectionIndex, setSectionIndex] = useState(0);
    const [maxExercisesPerMuscle, setMaxExercisesPerMuscle] = useState<number | ''>(initialLimits?.maxExercisesPerMuscle ?? '');
    const [maxRPE, setMaxRPE] = useState<number | ''>(initialLimits?.maxRPE ?? '');
    const [activeTab, setActiveTab] = useState<'defaults' | 'limits'>('defaults');

    useEffect(() => {
        if (isOpen && initialLimits) {
            setMaxExercisesPerMuscle(initialLimits.maxExercisesPerMuscle ?? '');
            setMaxRPE(initialLimits.maxRPE ?? '');
        }
    }, [isOpen, initialLimits?.maxExercisesPerMuscle, initialLimits?.maxRPE]);

    const handleApplyDefaults = () => {
        onApply({
            sets: sets === '' ? 3 : Number(sets),
            reps: reps === '' ? 10 : Number(reps),
            rpe: rpe === '' ? 8 : Number(rpe),
            scope,
            sectionIndex: scope === 'section' ? sectionIndex : undefined,
            action: 'defaults',
        });
        onClose();
    };

    const handleSaveLimits = () => {
        onApply({
            maxExercisesPerMuscle: maxExercisesPerMuscle === '' ? undefined : maxExercisesPerMuscle,
            maxRPE: maxRPE === '' ? undefined : maxRPE,
            action: 'limits',
        });
        onClose();
    };

    return (
        <Drawer isOpen={isOpen} onClose={onClose} title="Reglas" position="bottom" height="70%">
            <div className="p-4 space-y-4">
                <div className="flex gap-1 bg-white/5 p-1 rounded-lg">
                    <button onClick={() => setActiveTab('defaults')} className={`flex-1 py-2 text-[10px] font-bold rounded-md transition-all ${activeTab === 'defaults' ? 'bg-[#00F0FF] text-white' : 'text-[#999]'}`}>Defaults</button>
                    <button onClick={() => setActiveTab('limits')} className={`flex-1 py-2 text-[10px] font-bold rounded-md transition-all ${activeTab === 'limits' ? 'bg-[#00F0FF] text-white' : 'text-[#999]'}`}>Límites</button>
                </div>

                {activeTab === 'defaults' && (
                    <>
                        <p className="text-xs text-[#999] leading-relaxed">Aplica valores por defecto a ejercicios.</p>
                        <div>
                            <span className="text-[10px] font-bold text-[#555] uppercase block mb-2">Ámbito</span>
                            <div className="flex gap-2 flex-wrap">
                                {(['session', 'section'] as const).map(s => (
                                    <button key={s} onClick={() => setScope(s)} className={`px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all ${scope === s ? 'bg-[#00F0FF] text-white' : 'bg-white/5 text-[#999]'}`}>
                                        {s === 'session' ? 'Toda la sesión' : 'Sección'}
                                    </button>
                                ))}
                            </div>
                            {scope === 'section' && sectionNames.length > 0 && (
                                <select value={sectionIndex} onChange={e => setSectionIndex(parseInt(e.target.value))} className="mt-2 w-full bg-[#0d0d0d] border border-[#E6E0E9] rounded-lg text-xs text-white py-2 px-3">
                                    {sectionNames.map((name, i) => (
                                        <option key={i} value={i} className="bg-black">{name || `Sección ${i + 1}`}</option>
                                    ))}
                                </select>
                            )}
                        </div>
                        <div className="grid grid-cols-3 gap-3">
                            <div>
                                <span className="text-[10px] font-bold text-[#555] uppercase block mb-1">Series</span>
                                <input type="number" min={1} max={20} value={sets === '' ? '' : sets} onChange={e => { const v = e.target.value; setSets(v === '' ? '' : Math.min(20, Math.max(1, parseInt(v, 10) || 3))); }} className="w-full bg-[#0d0d0d] border border-cyber-cyan/20 rounded-lg focus:border-[#00F0FF] text-sm font-mono text-white py-1.5 text-center outline-none" />
                            </div>
                            <div>
                                <span className="text-[10px] font-bold text-[#555] uppercase block mb-1">Reps</span>
                                <input type="number" min={1} max={99} value={reps === '' ? '' : reps} onChange={e => { const v = e.target.value; setReps(v === '' ? '' : Math.min(99, Math.max(1, parseInt(v, 10) || 10))); }} className="w-full bg-[#0d0d0d] border border-cyber-cyan/20 rounded-lg focus:border-[#00F0FF] text-sm font-mono text-white py-1.5 text-center outline-none" />
                            </div>
                            <div>
                                <span className="text-[10px] font-bold text-[#555] uppercase block mb-1">RPE</span>
                                <input type="number" step="0.5" min={1} max={10} value={rpe === '' ? '' : rpe} onChange={e => { const v = e.target.value; setRpe(v === '' ? '' : Math.min(10, Math.max(1, parseFloat(v) || 8))); }} className="w-full bg-[#0d0d0d] border border-cyber-cyan/20 rounded-lg focus:border-[#00F0FF] text-sm font-mono text-white py-1.5 text-center outline-none" />
                            </div>
                        </div>
                    </>
                )}

                {activeTab === 'limits' && (
                    <>
                        <p className="text-xs text-[#999] leading-relaxed">Límites y restricciones (aviso al superar).</p>
                        <div>
                            <span className="text-[10px] font-bold text-[#555] uppercase block mb-1">Máx ejercicios por músculo</span>
                            <input type="number" min={1} max={20} value={maxExercisesPerMuscle} onChange={e => setMaxExercisesPerMuscle(e.target.value === '' ? '' : Math.min(20, Math.max(1, parseInt(e.target.value) || 0)))} placeholder="Sin límite" className="w-full bg-[#0d0d0d] border border-cyber-cyan/20 rounded-lg focus:border-[#00F0FF] text-sm font-mono text-white py-1.5 px-3 outline-none placeholder-[#555]" />
                        </div>
                        <div>
                            <span className="text-[10px] font-bold text-[#555] uppercase block mb-1">RPE máximo (aviso si se supera)</span>
                            <input type="number" step="0.5" min={1} max={10} value={maxRPE} onChange={e => setMaxRPE(e.target.value === '' ? '' : Math.min(10, Math.max(1, parseFloat(e.target.value) || 0)))} placeholder="Sin límite" className="w-full bg-[#0d0d0d] border border-cyber-cyan/20 rounded-lg focus:border-[#00F0FF] text-sm font-mono text-white py-1.5 px-3 outline-none placeholder-[#555]" />
                        </div>
                    </>
                )}

                {activeTab === 'defaults' ? (
                    <button onClick={handleApplyDefaults} className="w-full py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">
                        Aplicar defaults
                    </button>
                ) : (
                    <button onClick={handleSaveLimits} className="w-full py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">
                        Guardar límites
                    </button>
                )}
            </div>
        </Drawer>
    );
};

/* ═══════════ Save Drawer ═══════════ */
interface SaveDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    sessionName: string;
    modifiedSessions: Session[];
    showBlockOption: boolean;
    onSaveSingle: (applyToBlock: boolean) => void;
    onSaveMultiple: (sessions: Session[], blockSelections: Record<string, boolean>) => void;
}

export const SaveDrawer: React.FC<SaveDrawerProps> = ({ isOpen, onClose, sessionName, modifiedSessions, showBlockOption, onSaveSingle, onSaveMultiple }) => {
    const [applyToBlock, setApplyToBlock] = useState(false);
    const [blockSelections, setBlockSelections] = useState<Record<string, boolean>>({});
    const isMultiple = modifiedSessions.length > 1;

    return (
        <Drawer isOpen={isOpen} onClose={onClose} title="Confirmar Cambios" position="bottom" height={isMultiple ? '65%' : '40%'}>
            <div className="p-4 space-y-4">
                {isMultiple ? (
                    <>
                        <p className="text-xs text-[#999]">Has modificado {modifiedSessions.length} sesiones:</p>
                        <div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar">
                            {modifiedSessions.map(s => (
                                <div key={s.id} className="flex items-center justify-between p-3 border border-white/[0.06] rounded-lg">
                                    <div className="flex items-center gap-2">
                                        <CheckIcon size={14} className="text-[#00F19F]" />
                                        <span className="text-xs font-medium text-white">{s.name || 'Sin nombre'}</span>
                                    </div>
                                    {showBlockOption && (
                                        <label className="flex items-center gap-1.5 cursor-pointer">
                                            <input type="checkbox" checked={blockSelections[s.id] || false} onChange={e => setBlockSelections(prev => ({ ...prev, [s.id]: e.target.checked }))} className="rounded border-[#E6E0E9] bg-black w-3 h-3 text-[#00F0FF] focus:ring-0" />
                                            <span className="text-[10px] text-[#555]">Bloque</span>
                                        </label>
                                    )}
                                </div>
                            ))}
                        </div>
                        <div className="flex gap-2 pt-2">
                            <button onClick={() => onSaveSingle(false)} className="flex-1 py-2.5 rounded-lg border border-white/[0.08] text-xs font-medium text-[#999] hover:text-white hover:bg-white/5 transition-all">Solo actual</button>
                            <button onClick={() => onSaveMultiple(modifiedSessions, blockSelections)} className="flex-1 py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">Guardar todas</button>
                        </div>
                    </>
                ) : (
                    <>
                        <p className="text-sm text-[#999]">Guardar cambios en <strong className="text-white">{sessionName}</strong></p>
                        {showBlockOption && (
                            <label className="flex items-center gap-3 p-3 border border-white/[0.08] rounded-lg cursor-pointer hover:bg-white/[0.02] transition-colors">
                                <input type="checkbox" checked={applyToBlock} onChange={e => setApplyToBlock(e.target.checked)} className="rounded border-[#E6E0E9] bg-black w-4 h-4 text-[#00F0FF] focus:ring-0" />
                                <div>
                                    <span className="text-xs font-bold text-white block">Aplicar a todo el bloque</span>
                                    <span className="text-[10px] text-[#555]">Cambia este día en todas las semanas restantes.</span>
                                </div>
                            </label>
                        )}
                        <div className="flex gap-2 pt-2">
                            <button onClick={onClose} className="flex-1 py-2.5 rounded-lg border border-white/[0.08] text-xs font-medium text-[#999] hover:text-white hover:bg-white/5 transition-all">Cancelar</button>
                            <button onClick={() => onSaveSingle(applyToBlock)} className="flex-1 py-2.5 rounded-lg bg-[#00F0FF] text-white text-xs font-bold hover:brightness-110 transition-all">Guardar</button>
                        </div>
                    </>
                )}
            </div>
        </Drawer>
    );
};

export { Drawer };
